import type { DocsCopy } from './docsCopy';

export type DeepPartial<T> = T extends readonly (infer Item)[]
  ? Array<DeepPartial<Item>>
  : T extends object
    ? { [Key in keyof T]?: DeepPartial<T[Key]> }
    : T;

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function mergeValue(base: unknown, override: unknown): unknown {
  if (override === undefined) return base;
  if (Array.isArray(base) && Array.isArray(override)) {
    return base.map((item, index) => index < override.length ? mergeValue(item, override[index]) : item);
  }
  if (isRecord(base) && isRecord(override)) {
    const result: Record<string, unknown> = { ...base };
    for (const [key, value] of Object.entries(override)) {
      result[key] = mergeValue(result[key], value);
    }
    return result;
  }
  return override;
}

export function mergeDocsCopy(base: DocsCopy, override: DeepPartial<DocsCopy>): DocsCopy {
  return mergeValue(base, override) as DocsCopy;
}

