function localizeIntegrationFields(copy: DocsCopy, locale: Locale): DocsCopy {
  const labels = fieldLabels[locale];
  const values = fieldValues[locale];
  if (!labels && !values) return copy;

  const localizeField = (field: { label: string; value: string }) => ({
    ...field,
    label: labels?.[field.label] ?? field.label,
    value: values?.[field.value] ?? field.value,
  });

  return {
    ...copy,
    integrations: {
      ...copy.integrations,
      connectionFields: copy.integrations.connectionFields.map(localizeField),
      guides: copy.integrations.guides.map((guide) => ({
        ...guide,
        fields: guide.fields.map(localizeField),
      })),
    },
  };
}

export function localizeDocsCopy(base: DocsCopy, locale: Locale): DocsCopy {
  const override = overrides[locale];
  const localized = override ? mergeDocsCopy(base, override) : base;
  return localizeIntegrationFields(localized, locale);
}
